[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectDir,[Parameter(Mandatory=$true)][string]$OutputFile,[Parameter(Mandatory=$true)][string]$Metadata)
$ErrorActionPreference='Stop';$source=[IO.Path]::GetFullPath($ProjectDir);if(!(Test-Path $source)){throw 'De projectmap bestaat niet.'};$output=[IO.Path]::GetFullPath($OutputFile);$parent=Split-Path $output;New-Item -ItemType Directory -Force $parent|Out-Null;$staging=Join-Path $env:TEMP ("localdeck-export-"+[guid]::NewGuid().ToString('N'));try{New-Item -ItemType Directory $staging|Out-Null;Copy-Item (Join-Path $source '*') $staging -Recurse -Force;Set-Content (Join-Path $staging '.localdeck-export.json') $Metadata -Encoding UTF8;if(Test-Path $output){Remove-Item -LiteralPath $output -Force};Compress-Archive -Path (Join-Path $staging '*') -DestinationPath $output -CompressionLevel Optimal}finally{if(Test-Path $staging){Remove-Item -LiteralPath $staging -Recurse -Force}}
